#nullable enable
using System.IO;
using NeoCompose.Runtime;
using NeoCompose.Runtime.Json;
using NUnit.Framework;
using UnityEngine;

namespace NeoCompose.Tests
{
    // Fixture generated by neo-compose cli/src/commands/nested-color-reference.test.ts.
    public class NestedColorReferenceTests
    {
        [Test]
        public void NestedDefaultReferenceAgreesWithDirectSlotAcrossFreshLoads()
        {
            for (int load = 0; load < 2; load++)
            {
                var data = NeoTestExport.Read(File.ReadAllText("Packages/com.ryanbliss.neocompose/Tests/nested-color-export.json"));
                using var client = NeoTestSaveStack.ClientFromSchema(data, assumeCurrentSchema: false);
                var reference = client.assets.Get<NeoMemberClass>("Item").Get<NeoMemberLookup>("HitParticleColor");
                var selected = NeoGeneratedTypesSupport.ReadReference<Color>(client, reference);
                var cold = selected!.Value;
                var direct = client.assets.Get<NeoMemberClass>("Design").Get<NeoMemberClass>("PrimaryPalette")
                    .Get<NeoMemberClass>("Orange").Get<NeoMemberColor>("Darker");
                Assert.AreEqual(new Color(0.3765f, 0.1725f, 0.1725f, 1), cold);
                Assert.AreEqual(new NeoReadOnlyColor(direct).Value, selected.Value);
                Assert.AreEqual(direct.overrideValueId, selected.TargetId);
            }
        }

        [Test]
        public void DeletedColorTargetStillReportsDanglingReference()
        {
            var data = NeoTestExport.Read(File.ReadAllText("Packages/com.ryanbliss.neocompose/Tests/nested-color-export.json"));
            using var client = NeoTestSaveStack.ClientFromSchema(data, assumeCurrentSchema: false);
            var colors = client.session.Get<NeoMemberListWritable>("Colors");
            var reference = NeoGeneratedTypesSupport.ReadReference<Color>(client, (object)colors[0].overrideValueId!)!;
            Assert.AreEqual(new Color(0.3765f, 0.1725f, 0.1725f, 1), reference.Value);
            colors.RemoveAt(0);
            StringAssert.Contains($"names value '{reference.TargetId}', which no longer exists", Assert.Catch(() => _ = reference.Value)!.Message);
        }
    }
}
